                    <h3 id="terms-title">{{ shown.title }}</h3>
                    <app-rich-text [blocks]="shown.blocks" [headingLevel]="4" />
                  </div>
                }
              }
            }
          </section>
        </div>

        <div class="payment">
          @if (termsStatus() === 'shown') {
            <div class="accept">
              <input id="accept-terms" type="checkbox" [checked]="accepted()" [disabled]="processing()" (change)="accept($event)" />
              <label for="accept-terms">Acepto los términos y condiciones</label>
            </div>
          }
          <fieldset class="simulation" [disabled]="processing()">
            <legend>Simulación de pago (no se realiza ningún cobro)</legend>
            <label class="choice">
              <input type="radio" name="simulation" value="approved" [checked]="outcome() === 'approved'" (change)="chooseOutcome('approved')" />
              Pago aprobado
            </label>
            <label class="choice">
              <input type="radio" name="simulation" value="rejected" [checked]="outcome() === 'rejected'" (change)="chooseOutcome('rejected')" />
              Pago rechazado
            </label>
          </fieldset>
          @if (showHint()) {
            <p id="pay-hint" class="hint">Acepta los términos y condiciones para pagar.</p>
          }
          <div class="actions">
            <button type="button" class="pay" [attr.aria-disabled]="canPay() ? null : 'true'" [attr.aria-describedby]="showHint() ? 'pay-hint' : null" (click)="pay()">
              {{ processing() ? 'Procesando pago…' : 'Pagar' }}
            </button>
          </div>
          @if (paymentState() === 'rejected') {
            <p role="alert" class="message--error">El pago fue rechazado y no se realizó ningún cobro. Puedes intentarlo de nuevo.</p>
          }
        </div>
      }
    }
  }
  <div role="status" class="visually-hidden">{{ processing() ? 'Procesando pago…' : '' }}</div>
</main>
