  }
</ng-template>

<ng-template #itemTpl let-item>
  <li>
    <ng-container *ngTemplateOutlet="spansTpl; context: { $implicit: item.spans }" />
    @for (nested of item.lists; track $index) {
      <ng-container *ngTemplateOutlet="listTpl; context: { $implicit: nested }" />
    }
  </li>
</ng-template>

<ng-template #listTpl let-list>
  @if (list.ordered) {
    <ol>
      @for (item of list.items; track $index) {
        <ng-container *ngTemplateOutlet="itemTpl; context: { $implicit: item }" />
      }
