export function composite(over: RGBA, under: RGB): RGB {
  const mix = (o: number, u: number): number => Math.round(o * over.alpha + u * (1 - over.alpha));
  return [mix(over.rgb[0], under[0]), mix(over.rgb[1], under[1]), mix(over.rgb[2], under[2])];
}

