  });

  it('US-04-AC-09 the older weekInfo accessor is used when getWeekInfo does not exist', () => {
    expect(firstDayOfWeek('xx', () => ({ weekInfo: { firstDay: 7 } }))).toBe(7);
  });

  it('US-04-AC-09 getWeekInfo wins over weekInfo when both exist', () => {
