  color: var(--component-plan-recommended-check);
}
.choose-message {
  margin-top: var(--space-4);
}
.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin-top: var(--space-6);
}
@media (min-width: 37.5em) {
  .plans {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (min-width: 64em) {
