@media (prefers-reduced-motion: no-preference) {
  .panel {
    animation: panel-enter var(--duration-fast) var(--ease-out) backwards;
  }
  .panel:nth-of-type(2) {
    animation-delay: var(--delay-stagger-2);
  }
  .panel:nth-of-type(3) {
    animation-delay: var(--delay-stagger-3);
  }
  .panel:nth-of-type(4) {
    animation-delay: var(--delay-stagger-4);
  }
  .segment {
    transition: background-color var(--duration-base) var(--ease-standard);
  }
  .confirm-enter {
    animation: confirm-enter var(--duration-slow) var(--ease-out) backwards;
  }
  @keyframes panel-enter {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
  @keyframes confirm-enter {
    from {
      opacity: 0;
      transform: scale(0.85);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }
}
