  margin: calc((var(--size-target-min) - var(--size-icon)) / 2) 0 0;
  accent-color: var(--color-brand);
}
.accept__label {
  display: flex;
  align-items: center;
  min-height: var(--size-target-min);
}
/* The simulation group is a native radio group drawn as a pill segmented control. */
.simulation {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.simulation legend {
  padding: 0;
  margin-bottom: var(--space-2);
  font-weight: var(--weight-semibold);
}
.segments {
  display: flex;
  padding: var(--space-1);
  border: var(--border-width-hairline) solid var(--color-border-control);
  border-radius: var(--radius-pill);
  background: var(--component-input-bg);
}
.segment {
  position: relative;
  display: flex;
  flex: 1 1 0;
  align-items: center;
  justify-content: center;
  min-height: var(--size-target-min);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-pill);
  text-align: center;
  cursor: pointer;
}
.segment input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}
.segment:has(input:checked) {
  background: var(--component-segment-selected-bg);
  color: var(--component-segment-selected-text);
  font-weight: var(--weight-semibold);
}
.segment:has(input:focus-visible) {
  outline: var(--focus-ring-width) solid var(--color-focus);
  outline-offset: var(--focus-ring-offset);
}
.simulation:disabled {
  opacity: 0.6;
}
.pay {
  width: 100%;
}
.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
}
.confirmation {
  display: grid;
  justify-items: start;
  gap: var(--space-4);
}
.confirmation__icon {
  width: var(--size-icon-large);
  height: var(--size-icon-large);
  color: var(--color-success);
}
.confirmation__code {
  display: block;
  margin-top: var(--space-1);
  font-family: var(--font-display);
  font-size: var(--text-heading);
  font-stretch: var(--text-heading-stretch);
  overflow-wrap: anywhere;
}
@media (min-width: 37.5em) {
  .row {
    grid-template-columns: 12rem 1fr;
    gap: var(--space-4);
  }
  .pay {
    width: auto;
    min-width: var(--size-button-min);
  }
}
@media (forced-colors: active) {
  .segment:has(input:checked) {
    background: Highlight;
    color: HighlightText;
  }
}
@media (prefers-reduced-motion: no-preference) {
  .panel {
    animation: panel-enter var(--duration-fast) var(--ease-out) backwards;
  }
  .panel:nth-of-type(2) {
    animation-delay: var(--delay-stagger-2);
  }
  .panel:nth-of-type(3) {
    animation-delay: var(--delay-stagger-3);
  }
  .panel:nth-of-type(4) {
    animation-delay: var(--delay-stagger-4);
  }
  .segment {
    transition: background-color var(--duration-base) var(--ease-standard);
  }
  .confirm-enter {
    animation: confirm-enter var(--duration-slow) var(--ease-out) backwards;
  }
  @keyframes panel-enter {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
  @keyframes confirm-enter {
    from {
      opacity: 0;
      transform: scale(0.85);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }
}
