    let box=control.parentElement; while(box&&!box.contains(label)) box=box.parentElement;
    const icon=box?.querySelector('svg'); const r=icon.getBoundingClientRect();
    const top=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2); n++;
    if(top?.closest('svg')!==icon) found.push(label.textContent+' '+top?.tagName);
  }
  return {n,found};
}));
}
await b.close();
EOF
